(() => {
  'use strict';
  const G=window.WuyiGenerative,C=window.WUYI_FIELD_CONTENT,canvas=document.querySelector('#field');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)'),coarse=matchMedia('(pointer: coarse)');
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  let seed=readSeed(),width=innerWidth,height=innerHeight,time=0,paused=reduced.matches,dirty=true,lastStamp=0,lastRemix=0,lastInteraction=performance.now();
  let camera={x:0,y:0,z:reduced.matches?0:-650},target={x:0,y:0,z:0},view=[0,0,0],pointer={x:0,y:0},motion=0,selected=null,hovered=null,gesture=null,clickOrigin=null,suppressClick=false,toastTimer;
  const pointers=new Map(),tooltip=document.querySelector('#field-tooltip');
  function freshSeed(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]||1;}
  function readSeed(){const value=new URL(location.href).searchParams.get('seed');return value&&/^\d{1,10}$/.test(value)?Number(value)>>>0:261026;}
  function status(text){const toast=document.querySelector('#toast');toast.textContent=text;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),3100);}
  const space=new window.WuyiSpace(canvas,C.images,seed,message=>{dirty=true;if(message)status(message);});
  function sourceFor(tile){if(tile.index!==undefined&&space.available)return space.sourceFor(tile).image;if(tile.photo!==null&&tile.photo!==undefined)return directSources[tile.photo].image;if(!tile.texture)tile.texture=G.texture(tile.hash,tile.mode);return tile.texture;}
  function photoFor(tile){return tile.index===undefined?tile.photo:tile.index<space.photoCount?tile.index:null;}
  function modeFor(tile){return tile.mode===undefined?(tile.index-space.photoCount)%3:tile.mode;}
  function titleFor(tile){const photo=photoFor(tile);return photo===null?C.proceduralNames[modeFor(tile)]:C.images[photo].title;}
  function noteFor(tile){const photo=photoFor(tile);return photo===null?'程序生成纹理 · 浏览器内的视觉实验':C.images[photo].note;}
  const directSources=C.images.map(item=>{const image=new Image();image.src=item.src;return{...item,image};});
  function explore(){document.body.classList.add('is-exploring');lastInteraction=performance.now();}
  function updateSeed(){document.querySelector('#seed-label').textContent=seed.toString(16).toUpperCase().padStart(8,'0');}
  function resize(){width=innerWidth;height=innerHeight;space.resize(width,height,Math.min(devicePixelRatio||1,coarse.matches?1.25:1.5));dirty=true;}
  function syncPause(){document.querySelector('#pause').setAttribute('aria-pressed',String(paused));document.querySelector('#pause').textContent=paused?'继续漫游':'暂停漫游';document.body.classList.toggle('field-paused',paused);dirty=true;}
  function reset(){target={x:0,y:0,z:0};pointer={x:0,y:0};document.body.classList.remove('is-exploring');lastInteraction=performance.now();dirty=true;}
  function travel(distance){target.z+=distance;explore();dirty=true;}
  function newSeed(){seed=freshSeed();if(space.available)space.setSeed(seed);hovered=null;time=0;lastRemix=0;reset();updateSeed();status('另一片想象，正在展开。');}
  function render(stamp){requestAnimationFrame(render);if(document.hidden){lastStamp=stamp;return;}if(stamp-lastStamp<1000/(coarse.matches?30:45))return;const dt=lastStamp?Math.min((stamp-lastStamp)/1000,.06):0;lastStamp=stamp;const modal=Boolean(document.querySelector('dialog[open]'));
    if(!paused&&!modal)time+=dt;
    if(!paused&&!modal&&!gesture&&stamp-lastInteraction>5000){target.z+=dt*35;target.x+=dt*2;}
    let moving=Math.abs(target.x-camera.x)+Math.abs(target.y-camera.y)+Math.abs(target.z-camera.z)>0.1;
    const newView=reduced.matches?[0,0,0]:[-pointer.y*.075,pointer.x*.10,clamp((target.x-camera.x)*.00009,-.02,.02)];
    for(let i=0;i<3;i++){if(Math.abs(newView[i]-view[i])>.0001)moving=true;view[i]+=(newView[i]-view[i])*(reduced.matches?1:1-Math.exp(-dt*4));}
    if((paused||modal)&&!dirty&&!moving)return;
    const smoothing=reduced.matches?1:1-Math.exp(-dt*4.3);motion=clamp((Math.abs(target.z-camera.z)+Math.abs(target.x-camera.x))*.0005,0,1);camera.x+=(target.x-camera.x)*smoothing;camera.y+=(target.y-camera.y)*smoothing;camera.z+=(target.z-camera.z)*smoothing;
    space.draw({camera,view,time,motion:reduced.matches?0:motion,paused:paused||reduced.matches});
    canvas.dataset.renderer=space.available?'webgl':'fallback';canvas.dataset.depth=String(Math.round(camera.z));canvas.dataset.frames=String(space.visible.length);document.querySelector('#zoom-value').textContent=String(Math.max(0,Math.round(camera.z))).padStart(4,'0');
    if(!paused&&!modal&&!gesture&&time-lastRemix>8){lastRemix=time;if(space.available)space.remix();}
    dirty=moving;
  }
  function updateHover(event){hovered=space.available?space.hit(event.clientX,event.clientY):null;space.hovered=hovered;canvas.classList.toggle('hover-frame',Boolean(hovered));if(hovered&&!coarse.matches&&!gesture){tooltip.textContent=`${titleFor(hovered)} ↗`;tooltip.style.left=`${Math.min(event.clientX+18,width-170)}px`;tooltip.style.top=`${Math.min(event.clientY+18,height-80)}px`;tooltip.classList.add('visible');}else tooltip.classList.remove('visible');dirty=true;}
  function snapshot(){const a=[...pointers.values()];return a.length>1?{type:'pinch',distance:Math.hypot(a[1].x-a[0].x,a[1].y-a[0].y),x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2,camera:{...target}}:{type:'pan',x:a[0].x,y:a[0].y,camera:{...target}};}
  canvas.addEventListener('pointerdown',event=>{if(event.button!==0)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(event.pointerId);pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});gesture=snapshot();if(pointers.size===1){clickOrigin={x:event.clientX,y:event.clientY};suppressClick=false;}else suppressClick=true;lastInteraction=performance.now();canvas.classList.add('dragging');tooltip.classList.remove('visible');});
  canvas.addEventListener('pointermove',event=>{if(!coarse.matches&&!reduced.matches&&!paused){pointer={x:event.clientX/width-.5,y:event.clientY/height-.5};}if(!pointers.has(event.pointerId)){updateHover(event);return;}pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(!gesture)return;const a=[...pointers.values()];const factor=width<650?4:2.4;
    if(gesture.type==='pinch'&&a.length>1){const distance=Math.hypot(a[1].x-a[0].x,a[1].y-a[0].y);target.z=gesture.camera.z+Math.log(distance/Math.max(gesture.distance,1))*2300;const cx=(a[0].x+a[1].x)/2,cy=(a[0].y+a[1].y)/2;target.x=gesture.camera.x-(cx-gesture.x)*factor;target.y=gesture.camera.y+(cy-gesture.y)*factor;explore();}
    else{target.x=gesture.camera.x-(event.clientX-gesture.x)*factor;target.y=gesture.camera.y+(event.clientY-gesture.y)*factor;if(clickOrigin&&Math.hypot(event.clientX-clickOrigin.x,event.clientY-clickOrigin.y)>6){suppressClick=true;explore();}}dirty=true;lastInteraction=performance.now();
  });
  function pointerEnd(event){const tile=!suppressClick&&gesture?.type==='pan'&&space.available?space.hit(event.clientX,event.clientY):null;pointers.delete(event.pointerId);if(pointers.size){gesture=snapshot();suppressClick=true;}else{gesture=null;canvas.classList.remove('dragging');}if(tile)openFrame({...tile});lastInteraction=performance.now();dirty=true;}
  canvas.addEventListener('pointerup',pointerEnd);canvas.addEventListener('pointercancel',event=>{pointers.delete(event.pointerId);gesture=pointers.size?snapshot():null;suppressClick=true;canvas.classList.remove('dragging');});canvas.addEventListener('pointerleave',()=>{hovered=null;space.hovered=null;pointer={x:0,y:0};tooltip.classList.remove('visible');canvas.classList.remove('hover-frame');dirty=true;});
  canvas.addEventListener('wheel',event=>{event.preventDefault();const delta=clamp(event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?height:1),-600,600);if(event.shiftKey){target.x+=delta*2.2;explore();dirty=true;}else travel(delta*(event.ctrlKey?8:2.7));},{passive:false});
  document.querySelector('#brand-home').addEventListener('click',e=>{e.preventDefault();reset();});document.querySelector('#reset').addEventListener('click',reset);document.querySelector('#new-seed').addEventListener('click',newSeed);document.querySelector('#pause').addEventListener('click',()=>{paused=!paused;pointer={x:0,y:0};syncPause();});document.querySelector('#zoom-out').addEventListener('click',()=>travel(-900));document.querySelector('#zoom-in').addEventListener('click',()=>travel(900));
  canvas.addEventListener('keydown',event=>{const moves={ArrowLeft:[-260,0],ArrowRight:[260,0],ArrowUp:[0,260],ArrowDown:[0,-260],a:[-260,0],d:[260,0]};if(moves[event.key]){event.preventDefault();target.x+=moves[event.key][0];target.y+=moves[event.key][1];explore();dirty=true;}else if(['+','=','w','W'].includes(event.key)){event.preventDefault();travel(600);}else if(['-','s','S'].includes(event.key)){event.preventDefault();travel(-600);}else if(event.key===' '){event.preventDefault();paused=!paused;syncPause();}else if(event.key==='Home'){event.preventDefault();reset();}else if(event.key==='Enter'){event.preventDefault();const nearest=[...space.visible].filter(v=>v.depth>420).sort((a,b)=>Math.hypot(a.center.x-width/2,a.center.y-height/2)-Math.hypot(b.center.x-width/2,b.center.y-height/2))[0];if(nearest)openFrame({...nearest.tile});}});
  reduced.addEventListener('change',event=>{paused=event.matches;pointer={x:0,y:0};syncPause();});document.addEventListener('visibilitychange',()=>{dirty=true;lastStamp=0;});window.addEventListener('resize',resize);
  const frameDialog=document.querySelector('#frame-dialog'),preview=document.querySelector('#frame-preview'),previewContext=preview.getContext('2d');
  function openFrame(tile){selected=tile;const image=sourceFor(tile);preview.width=1280;preview.height=Math.round(1280*(image.naturalHeight||image.height)/(image.naturalWidth||image.width));G.cover(previewContext,image,0,0,preview.width,preview.height);preview.setAttribute('aria-label',`${titleFor(tile)}，${noteFor(tile)}`);document.querySelector('#frame-title').textContent=titleFor(tile);document.querySelector('#frame-note').textContent=`${noteFor(tile)} / ${tile.hash.toString(16).toUpperCase()}`;tooltip.classList.remove('visible');if(!frameDialog.open)frameDialog.showModal();}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  document.querySelector('#save-frame').addEventListener('click',()=>{if(!selected)return;preview.toBlob(blob=>{if(blob)download(blob,`WUYI-${selected.hash.toString(16)}.png`);},'image/png');});
  document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dirty=true;lastInteraction=performance.now();});dialog.addEventListener('click',event=>{const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();});});document.querySelector('#studio-open').addEventListener('click',()=>document.querySelector('#studio-dialog').showModal());document.querySelector('#brief-open').addEventListener('click',()=>document.querySelector('#brief-dialog').showModal());
  C.members.forEach((member,index)=>{const figure=document.createElement('figure'),image=document.createElement('img'),caption=document.createElement('figcaption'),small=document.createElement('span');image.src=member.image;image.alt=`无衣团队 ${member.name}`;image.loading='lazy';caption.append(document.createTextNode(member.name));small.textContent=`${String(index+1).padStart(2,'0')} / WUYI COLLECTIVE`;caption.append(small);figure.append(image,caption);document.querySelector('#team-grid').append(figure);});
  let indexBuilt=false;function buildIndex(){if(indexBuilt)return;indexBuilt=true;const grid=document.querySelector('#index-grid'),count=C.images.length;for(let i=0;i<count+3;i++){const tile={hash:G.hash(i,42,seed),photo:i<count?i:null,mode:(i-count+3)%3,texture:null};const button=document.createElement('button'),image=document.createElement('img'),title=document.createElement('strong'),note=document.createElement('small');button.className='index-card';image.src=i<count?C.images[i].src:sourceFor(tile).toDataURL('image/webp');image.alt='';title.textContent=titleFor(tile);note.textContent=i<count?'AI GENERATED PLACEHOLDER':'PROCEDURAL / TEXTURE';button.append(image,title,note);button.addEventListener('click',()=>{const src=sourceFor(tile);if(!(src.naturalWidth||src.width)){status('影像正在载入，请稍后再试。');return;}openFrame({...tile});});grid.append(button);}}
  document.querySelector('#index-open').addEventListener('click',()=>{buildIndex();document.querySelector('#index-dialog').showModal();});
  document.querySelector('#brief-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),text=`无衣 WUYI · 项目简报\n\n称呼：${data.get('name')}\n联系方式：${data.get('contact')}\n\n想法：\n${data.get('idea')}\n`;download(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}),'无衣-项目简报.txt');document.querySelector('#form-status').textContent=C.email?`简报已下载，可通过 ${C.email} 联系我们。`:'简报已下载至你的设备，信息未上传或发送。';});
  if(!space.available){document.body.classList.add('no-webgl');document.querySelector('#pause').disabled=true;document.querySelector('#zoom-in').disabled=true;document.querySelector('#zoom-out').disabled=true;status('当前浏览器无法展示三维空间，可从实验索引浏览。');}
  resize();updateSeed();syncPause();requestAnimationFrame(render);
})();
